# Regenerates data_meta_reml.csv and ref_meta_reml.csv (drmTMB 0.8.1, REML = TRUE, meta_V).
# Run: Rscript make_reference.R   (needs drmTMB installed)
suppressMessages(library(drmTMB))
set.seed(20261110)
k <- 40
d <- data.frame(g = factor(sample(sprintf("s%02d", 1:8), k, replace = TRUE)),
                x1 = rnorm(k), vi = runif(k, 0.05, 0.4))
u <- rnorm(8, 0, 0.5); names(u) <- sprintf("s%02d", 1:8)
d$yi <- 0.3 + 0.6 * d$x1 + u[as.character(d$g)] + rnorm(k, 0, 0.35) + rnorm(k, 0, sqrt(d$vi))
write.csv(d, "data_meta_reml.csv", row.names = FALSE)
# Second dataset: crossed (1 | g1) + (1 | g2), v_i over three orders of magnitude, 3-level factor moderator.
k2 <- 60
d2 <- data.frame(g1 = factor(sprintf("a%d", sample(1:6, k2, replace = TRUE))),
                 g2 = factor(sprintf("b%d", sample(1:5, k2, replace = TRUE))),
                 f = factor(sample(c("l1", "l2", "l3"), k2, replace = TRUE)),
                 x1 = rnorm(k2), vi = 10^runif(k2, -3, log10(5)))
u1 <- rnorm(6, 0, 0.5); names(u1) <- sprintf("a%d", 1:6)
u2 <- rnorm(5, 0, 0.3); names(u2) <- sprintf("b%d", 1:5)
d2$yi <- 0.2 + 0.5 * d2$x1 + c(l1 = 0, l2 = 0.4, l3 = -0.3)[as.character(d2$f)] +
  u1[as.character(d2$g1)] + u2[as.character(d2$g2)] + rnorm(k2, 0, 0.3) + rnorm(k2, 0, sqrt(d2$vi))
write.csv(d2, "data_meta_reml2.csv", row.names = FALSE)
rows <- list()
add <- function(cell, fit) {
  co <- summary(fit)$coefficients
  rows[[length(rows) + 1]] <<- data.frame(cell = cell, key = "logLik", est = as.numeric(logLik(fit)), se = NA)
  rows[[length(rows) + 1]] <<- data.frame(cell = cell, key = rownames(co), est = co[, "estimate"], se = co[, "std_error"])
  sdp <- summary(fit)$parameters
  sdp <- sdp[sdp$component == "random-effect-sd", ]
  for (j in seq_len(nrow(sdp)))
    # drmTMB reports the SD on the response scale with its delta-method SE (ADREPORT of exp(log_sd)),
    # so SE(log SD) = SE(SD) / SD exactly.
    rows[[length(rows) + 1]] <<- data.frame(cell = cell, key = paste0("sd_", rownames(sdp)[j]),
      est = sdp$estimate[j], se = sdp$std_error[j])
}
f1 <- drmTMB(bf(yi ~ x1 + meta_V(V = vi), sigma ~ 1), family = gaussian(), data = d, REML = TRUE)
f2 <- drmTMB(bf(yi ~ x1 + (1 | g) + meta_V(V = vi), sigma ~ 1), family = gaussian(), data = d, REML = TRUE)
f3 <- drmTMB(bf(yi ~ x1 + f + (1 | g1) + (1 | g2) + meta_V(V = vi), sigma ~ 1), family = gaussian(), data = d2, REML = TRUE)
f4 <- tryCatch(drmTMB(bf(yi ~ x1 + (1 | p | g) + meta_V(V = vi), sigma ~ 1), family = gaussian(), data = d, REML = TRUE),
               error = function(e) { cat("R labelled: ", conditionMessage(e), "\n"); NULL })
dm <- d; dm$x1[3] <- NA
f5 <- tryCatch(drmTMB(bf(yi ~ x1 + meta_V(V = vi), sigma ~ 1), family = gaussian(), data = dm, REML = TRUE),
               error = function(e) { cat("R missing predictor: ", conditionMessage(e), "\n"); NULL })
if (!is.null(f4)) add("meta_labelled_reml", f4)
if (!is.null(f5)) add("meta_missing_x_reml", f5)
add("meta_reml", f1); add("meta_re_reml", f2); add("meta_crossed_reml", f3)
ref <- do.call(rbind, rows); rownames(ref) <- NULL
hdr <- c(sprintf("# drmTMB %s; R %s; TMB %s; Matrix %s; %s",
                 as.character(packageVersion("drmTMB")), paste(R.version$major, R.version$minor, sep = "."),
                 as.character(packageVersion("TMB")), as.character(packageVersion("Matrix")), R.version$platform),
         "# generated by make_reference.R (set.seed(20261110)); REML = TRUE; meta_V(V = vi)")
writeLines(hdr, "ref_meta_reml.csv")
suppressWarnings(write.table(ref, "ref_meta_reml.csv", sep = ",", row.names = FALSE, append = TRUE, qmethod = "double"))
print(ref, digits = 12); cat(hdr, sep = "\n")
